    sw t1, 24(t6)
    lui t1, 0x90
    addi t1, t1, -310
    sw t1, 28(t6)
    lui t1, 0x28000
    addi t1, t1, 69
    sw t1, 32(t6)
    addi t1, zero, 256
    sw t1, 36(t6)
    addi t1, zero, 1600
    sw t1, 40(t6)
    lui t1, 0x6404b
    addi t1, t1, -1856
    sw t1, 44(t6)
    addi t1, zero, 0
    sw t1, 48(t6)
    sw s6, 48(t6)
    lui t0, 0x5
    sh t0, 52(t6)
    sh s7, 54(t6)
    lui t0, 0x5f001
    sw t0, 56(t6)
    mv a0, s11
    jal ra, ws_bswap
    sw a0, 60(t6)
    lui t0, 0x1
    addi t0, t0, 336
    sh t0, 64(t6)
    addi t0, zero, 32
    sh t0, 66(t6)
    sw zero, 68(t6)
    mv a0, t6
    addi a0, a0, 32
    addi a1, zero, 20
    jal ra, ws_cksum
    lui t0, 0x10
    addi t0, t0, -1
    xor a0, a0, t0
    srli t0, a0, 8
    sb t0, 42(t6)
    andi t0, a0, 0xFF
    sb t0, 43(t6)
    mv t5, t6
    addi t5, t5, 512
    lui t1, 0x6404b
    addi t1, t1, -1856
    sw t1, 0(t5)
    sw s6, 4(t5)
    lui t1, 0x14000
    addi t1, t1, 1536
    sw t1, 8(t5)
    mv a0, t5
    addi a1, zero, 12
    jal ra, ws_cksum
    mv s8, a0
    mv a0, t6
    addi a0, a0, 52
    addi a1, zero, 20
    jal ra, ws_cksum
    add a0, a0, s8
    srli t0, a0, 16
    lui t1, 0x10
    addi t1, t1, -1
    and a0, a0, t1
    add a0, a0, t0
    xor a0, a0, t1
    srli t0, a0, 8
    sb t0, 68(t6)
    andi t0, a0, 0xFF
    sb t0, 69(t6)
    addi a0, zero, 72
    jal ra, ws_tx_frame
    lw ra, 12(sp)
    addi sp, sp, 16
    jalr zero, 0(ra)
    ws_msg_accept:
    addi sp, sp, -16
    sw ra, 12(sp)
.Lr3: auipc a0, %pcrel_hi(.Ls3)
    addi a0, a0, %pcrel_lo(.Lr3)
    jal ra, print_string
    lw ra, 12(sp)
    addi sp, sp, 16
    jalr zero, 0(ra)
    ws_msg_got:
    addi sp, sp, -16
    sw ra, 12(sp)
.Lr4: auipc a0, %pcrel_hi(.Ls4)
    addi a0, a0, %pcrel_lo(.Lr4)
    jal ra, print_string
    lw ra, 12(sp)
    addi sp, sp, 16
    jalr zero, 0(ra)
    ws_msg_done:
    addi sp, sp, -16
    sw ra, 12(sp)
.Lr5: auipc a0, %pcrel_hi(.Ls5)
    addi a0, a0, %pcrel_lo(.Lr5)
    jal ra, print_string
    lw ra, 12(sp)
    addi sp, sp, 16
    jalr zero, 0(ra)

halt:
    j halt


print_string:                # a0 = ptr
    addi sp, sp, -16
    sw ra, 12(sp)
    sw t0, 8(sp)
    sw t1, 4(sp)
ps_loop:
    lbu t1, 0(a0)
    beqz t1, ps_done
    lui t0, 0x40070
    sw t1, 0(t0)
    addi a0, a0, 1
    j ps_loop
ps_done:
    lw ra, 12(sp)
    lw t0, 8(sp)
    lw t1, 4(sp)
    addi sp, sp, 16
    ret

print_hex32:                 # a0 = word: 8 hex digits + newline
    addi sp, sp, -16
    sw ra, 12(sp)
    sw t1, 8(sp)
    sw t2, 4(sp)
    addi t2, zero, 8
    mv t1, a0
hex_digit:
    srli a0, t1, 28
    slli t1, t1, 4
    addi t0, zero, 10
    bgeu a0, t0, hex_alpha
    addi a0, a0, 0x30
    j hex_out
hex_alpha:
    addi a0, a0, 0x37
hex_out:
    lui t0, 0x40070
    sw a0, 0(t0)
    addi t2, t2, -1
    bnez t2, hex_digit
    addi a0, zero, 0x0A
    lui t0, 0x40070
    sw a0, 0(t0)
    lw ra, 12(sp)
    lw t1, 8(sp)
    lw t2, 4(sp)
    addi sp, sp, 16
    ret

uart_getc:                   # -> a0 = byte (blocks)
    lui t0, 0x40070
ug_wait:
    lw t1, 0x18(t0)
    andi t1, t1, 0x10
    bnez t1, ug_wait
    lw a0, 0(t0)
    andi a0, a0, 0xFF
    ret


    .section .rodata
    .align 2
.Ls1: .asciz "RV32 Webserver Starting (.100:80 via PIO2)\n"
.Ls2: .asciz "RV32 WEBSERVER LISTEN\n"
.Ls3: .asciz "RV32 WEBSERVER ACCEPT\n"
.Ls4: .asciz "RV32 WEBSERVER GOT\n"
.Ls5: .asciz "RV32 WEBSERVER DONE\n"
